const t=(re)=>{try{const r=new RegExp(re,"u");return "OK "+r.test("")+" "+r.source}catch(e){return "FAIL "+e.message}};
for (const p of ["\\p{Nd}","\\p{White_Space}","\\p{Cc}","\\p{Cf}","\\p{Cs}","\\p{Co}","\\p{Cn}","\\p{Zl}","\\p{Zp}","\\p{Zs}","\\p{General_Category=Unassigned}"]) console.log(p, "=>", t(p));
