console.log("Nd test ٣:", /\p{Nd}/u.test("٣"), "² :", /\p{Nd}/u.test("²"), "Ⅵ:", /\p{Nd}/u.test("Ⅵ"));
console.log("WS \\x1c:", /\p{White_Space}/u.test("\x1c"), "NBSP:", /\p{White_Space}/u.test(" "), "ZWSP:", /\p{White_Space}/u.test("​"), "U+0085:", /\p{White_Space}/u.test(""), "\\v:", /\p{White_Space}/u.test("\v"));
console.log("Cn on U+0378:", /\p{Cn}/u.test("͸"));
console.log("bigint:", (123456789012345678901234567890n % 2n) === 0n);
console.log("digit run walkback for ၅ (U+1045):", 0x1045 - 0x1040);
'

