input.command:
cd /tmp && cat > nodeprobe.mjs <<'EOF'
const props = ["\\p{Nd}","\\p{White_Space}","\\p{Cc}","\\p{Cf}","\\p{Cs}","\\p{Co}","\\p{Cn}","\\p{Zl}","\\p{Zp}","\\p{Zs}"];
for (const p of props) {
  try { new RegExp(p, "u"); console.log(p, "=> SUPPORTED"); }
  catch (e) { console.log(p, "=> FAIL:", e.message); }
}
console.log("--- Nd ---");
console.log("arabic-indic 3:", /^\p{Nd}$/u.test("٣"), "super2:", /^\p{Nd}$/u.test("²"), "romanVI:", /^\p{Nd}$/u.test("Ⅵ"), "myanmar5:", /^\p{Nd}$/u.test("၅"));
console.log("--- White_Space ---");
for (const cp of [0x09,0x0a,0x0b,0x0c,0x0d,0x1c,0x1d,0x1e,0x1f,0x20,0x85,0xa0,0x1680,0x2000,0x200a,0x200b,0x2028,0x2029,0x202f,0x205f,0x3000]) {
  process.stdout.write("U+"+cp.toString(16).padStart(4,"0")+"="+(/\p{White_Space}/u.test(String.fromCodePoint(cp))?"Y":"n")+" ");
}
console.log("\n--- printable (Python isprintable) ---");
const NP = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;
for (const cp of [0x20,0x07,0x1c,0xa0,0x200b,0xe9,0x1f389,0x378,0x2028,0x3000]) {
  const ch = String.fromCodePoint(cp);
  console.log("  U+"+cp.toString(16).padStart(4,"0"), "nonprintable="+NP.test(ch));
}
console.log("--- digit run walkback ---");
const ndVal = (cp) => { let s = cp; while (s > 0 && cp - s < 9 && /^\p{Nd}$/u.test(String.fromCodePoint(s-1))) s--; return cp - s; };
for (const cp of [0x30,0x39,0x663,0x1045,0xff19,0x1d7ce,0x1e959]) console.log("  U+"+cp.toString(16), "->", ndVal(cp));
console.log("--- bigint ---");
console.log((-6n % 2n) === 0n, (-3n % 2n) === 0n, (123456789012345678901234567891n % 2n) === 0n);
EOF
node nodeprobe.mjs

