/**
 * A minimal `linecache` for the one lookup CPython's traceback machinery
 * performs in this program: `linecache.getline("test5.py", 8)`.
 *
 * SURPRISE: whether the reference prints a source-echo line and a `^^^^^^`
 * caret line in its traceback depends on the CURRENT WORKING DIRECTORY.
 *
 * The frozen binary carries no source, so the traceback's filename is the bare
 * relative string "test5.py" recorded at build time.  `linecache` resolves that
 * against the cwd; if a readable `test5.py` happens to sit there it echoes
 * whatever line 8 of *that* file says, and if not it silently degrades to just
 * the `File "test5.py", line 8, in <module>` header.  Verified both ways:
 * running from /workspace/dataset (which contains test5.py) yields the source
 * and caret lines, running from an empty directory yields neither.
 *
 * Note that PyInstaller does not put the script directory on sys.path, so the
 * lookup really is cwd-relative only -- a `test5.py` next to the executable is
 * NOT found.
 */

import { readFileSync } from 'node:fs';

/** Split like Python's `readlines()` over universal newlines. */
function splitLines(text) {
  return text.split(/\r\n|\r|\n/);
}

/**
 * `linecache.getline(filename, lineno)` -- returns `''` when the file cannot be
 * read or the line does not exist.  `lineno` is 1-based.
 */
export function getLine(filename, lineno) {
  let text;
  try {
    text = readFileSync(filename, 'utf8');
  } catch {
    return '';
  }
  const lines = splitLines(text);
  if (lineno < 1 || lineno > lines.length) return '';
  return lines[lineno - 1];
}

